{
  "name": "@tder311/opencode-orchestrator",
  "version": "0.1.0",
  "description": "Spawn and supervise parallel opencode agents in cmux tabs, each on its own git worktree",
  "type": "module",
  "main": "src/index.js",
  "license": "MIT",
  "author": "Tom Derrick",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tder311/opencode-orchestrator.git"
  },
  "homepage": "https://github.com/tder311/opencode-orchestrator#readme",
  "bugs": {
    "url": "https://github.com/tder311/opencode-orchestrator/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cmux",
    "orchestrator",
    "multi-agent",
    "worktree",
    "agents"
  ],
  "engines": {
    "node": ">=18"
  },
  "files": [
    "src",
    "profile",
    "commands",
    "install.sh",
    "orchestrator.json",
    "README.md",
    "AGENTS.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test test/*.test.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.13"
  }
}

import { tool } from "@opencode-ai/plugin";
import { existsSync, rmSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { runtime } from "./lib/runtime.js";
import { expandHome, flattenTask, nowIso } from "./lib/util.js";
import * as cmux from "./lib/cmux.js";
import * as git from "./lib/git.js";
import { registryPath, loadRegistry, upsertRepo } from "./lib/registry.js";
import { statePath, loadState, resolveAgent, updateAgent, removeAgent } from "./lib/state.js";
import { spawnAgent } from "./lib/spawn.js";
import { startWatcher } from "./lib/watcher.js";

const z = tool.schema;

// ── helpers ───────────────────────────────────────────────────────────

const exec = (...args) => runtime.exec(...args);

// Set at plugin init: this session's own opencode server URL, recorded as
// each agent's origin so this same instance's watcher can find and wake it.
let serverUrl = null;

function fail(err) {
  return `Error: ${err.message}`;
}

function resolveOrExplain(agent) {
  const { agent: record, matches = [] } = resolveAgent(statePath(), agent);
  if (record) return { record };
  if (matches.length > 1) {
    const list = matches.map((a) => `  - ${a.name} (${a.id}) [${a.status}]`).join("\n");
    return { error: `Multiple agents match '${agent}':\n${list}\nBe more specific.` };
  }
  return { error: `No agent matches '${agent}'. Run listagents to see active agents.` };
}

function formatAgent(a, { dirty, ahead } = {}) {
  const bits = [];
  if (dirty === true) bits.push("dirty");
  if (dirty === false) bits.push("clean");
  if (ahead) bits.push(`${ahead} ahead of ${a.baseBranch}`);
  if (a.lastReport) bits.push(`${a.lastReport.kind}: ${a.lastReport.message}`);
  if (a.lastReport?.reportPath) bits.push(`report: ${a.lastReport.reportPath}`);
  const suffix = bits.length ? ` — ${bits.join(" — ")}` : "";
  return `  ${a.name} (${a.id}) [${a.status}] ${a.repo}/${a.branch}${suffix}`;
}

// ── orchestrator-side tools ───────────────────────────────────────────

const spawnagent = tool({
  description:
    "Spawn a new agent: creates a git worktree for the given repo/branch, opens a cmux tab (background, same pane) running opencode in it, delivers the initial task via --prompt at boot, and starts a monitor that wakes THIS session when the agent reports. Requires a repos registry (~/.config/opencode/orchestrator/repos.json) — use registerrepo to add repos.",
  args: {
    repo: z.string().describe("Repo key from the registry (see registerrepo / orchestrator.json)"),
    branch: z
      .string()
      .describe("Branch for the agent to work on, e.g. feat/nem/battery-constraints. Created from base if it doesn't exist."),
    base: z.string().optional().describe("Base branch to create from (default: repo's origin/HEAD)"),
    name: z.string().optional().describe("Display/tab name (default: slugified branch)"),
    task: z.string().optional().describe("Initial task, delivered via --prompt when the agent boots"),
  },
  async execute(args, context) {
    try {
      const origin =
        serverUrl && context?.sessionID
          ? { serverUrl, sessionID: context.sessionID }
          : null;
      const { record, warnings } = await spawnAgent({ ...args, origin }, {
        exec: runtime.exec,
        env: process.env,
        registryFile: registryPath(),
        stateFile: statePath(),
        sleep: runtime.sleep,
      });
      const lines = [
        `✓ Agent spawned: ${record.name} (${record.id})`,
        `  Repo:     ${record.repo}  Branch: ${record.branch} (base ${record.baseBranch})`,
        `  Worktree: ${record.worktree}`,
        `  Tab:      ${record.tabRef} (background — user's focus untouched)`,
      ];
      if (record.origin) lines.push(`  Watched:  this session wakes on any report (in-process watcher)`);
      if (args.task) lines.push(`  Task:     delivered via --prompt at boot`);
      for (const w of warnings) lines.push(`  Warning: ${w}`);
      lines.push(
        ``,
        `Do NOT poll or watch it — it reports done/blocked/question via cmux notification.`,
        `Check listagents when the user asks. peekagent/sendtoagent only on request.`,
      );
      return lines.join("\n");
    } catch (err) {
      return fail(err);
    }
  },
});

const listagents = tool({
  description:
    "List all orchestrated agents: status (starting/working/idle/done/blocked/error), branch, dirty state, and their latest reportstatus report. Prunes records whose tab no longer exists.",
  args: {},
  async execute() {
    try {
      const file = statePath();
      let state = loadState(file);
      let agents = Object.values(state.agents);
      if (agents.length === 0) {
        return "No agents registered. Spawn one with spawnagent.";
      }

      // prune records whose tab is gone (best effort — skip if cmux unreachable)
      if (cmux.isCmux(process.env)) {
        try {
          const live = cmux.listSurfaceRefs(exec);
          const dead = agents.filter((a) => a.surfaceRef && !live.has(a.surfaceRef));
          for (const d of dead) removeAgent(file, d.id);
          state = loadState(file);
          agents = Object.values(state.agents);
        } catch {
          /* cmux unreachable — list without pruning */
        }
      }
      if (agents.length === 0) return "No live agents (all stale records were pruned).";

      const lines = ["Agents:"];
      for (const a of agents) {
        let dirty;
        let ahead = 0;
        if (a.worktree && existsSync(a.worktree)) {
          dirty = git.isDirty(a.worktree, exec);
          ahead = git.aheadCount(a.worktree, `origin/${a.baseBranch}`, exec);
        }
        lines.push(formatAgent(a, { dirty, ahead }));
        lines.push(`    worktree: ${a.worktree}`);
      }
      return lines.join("\n");
    } catch (err) {
      return fail(err);
    }
  },
});

const peekagent = tool({
  description: "Read the visible screen of an agent's cmux tab to see what it's doing or stuck on.",
  args: {
    agent: z.string().describe("Agent id, name, or unique substring of name/branch"),
    lines: z.number().optional().describe("How many screen lines to read (default 50)"),
  },
  async execute({ agent, lines }) {
    const { record, error } = resolveOrExplain(agent);
    if (error) return error;
    try {
      const screen = cmux.readScreen(record.surfaceRef, lines ?? 50, exec);
      return `--- ${record.name} (${record.surfaceRef}) ---\n${screen.trim()}`;
    } catch (err) {
      return fail(err);
    }
  },
});

const sendtoagent = tool({
  description:
    "Type a message into a running agent's opencode prompt (e.g. answer its question, change scope, nudge it). Newlines are flattened.",
  args: {
    agent: z.string().describe("Agent id, name, or unique substring of name/branch"),
    message: z.string().describe("Message to type into the agent's prompt"),
  },
  async execute({ agent, message }) {
    const { record, error } = resolveOrExplain(agent);
    if (error) return error;
    try {
      cmux.sendText(record.surfaceRef, flattenTask(message), exec);
      cmux.sendKey(record.surfaceRef, "enter", exec);
      updateAgent(statePath(), record.id, { status: "working" });
      return `✓ Sent to ${record.name}: ${flattenTask(message).slice(0, 100)}`;
    } catch (err) {
      return fail(err);
    }
  },
});

const focusagent = tool({
  description: "Switch the user's focus to an agent's cmux tab.",
  args: {
    agent: z.string().describe("Agent id, name, or unique substring of name/branch"),
  },
  async execute({ agent }) {
    const { record, error } = resolveOrExplain(agent);
    if (error) return error;
    try {
      cmux.focusSurface(record.surfaceRef, exec);
      return `✓ Focused ${record.name} (${record.tabRef})`;
    } catch (err) {
      return fail(err);
    }
  },
});

const closeagent = tool({
  description:
    "Close an agent's tab and remove its record. With remove:true also deletes the git worktree (refuses while the worktree has uncommitted changes unless force:true).",
  args: {
    agent: z.string().describe("Agent id, name, or unique substring of name/branch"),
    remove: z.boolean().optional().describe("Also delete the git worktree"),
    force: z.boolean().optional().describe("Delete the worktree even if it has uncommitted changes"),
  },
  async execute({ agent, remove, force }) {
    const { record, error } = resolveOrExplain(agent);
    if (error) return error;
    const notes = [];

    if (remove && record.worktree && existsSync(record.worktree)) {
      if (!force && git.isDirty(record.worktree, exec)) {
        return `Refusing to remove worktree — '${record.name}' has uncommitted changes.\nWorktree: ${record.worktree}\nCommit/stash them first, or call closeagent with force:true.`;
      }
      const repoPath = expandHome(
        loadRegistry(registryPath()).repos[record.repo]?.path ?? "",
      );
      if (!repoPath || !existsSync(repoPath)) {
        return `Cannot remove worktree: repo '${record.repo}' path unknown in registry. Tab left open.`;
      }
      try {
        git.removeWorktree(repoPath, record.worktree, { force: Boolean(force) }, exec);
        notes.push("worktree removed");
      } catch (err) {
        return fail(err);
      }
    }

    try {
      cmux.closeSurface(record.surfaceRef, exec);
      notes.push("tab closed");
    } catch {
      notes.push("tab already gone");
    }
    removeAgent(statePath(), record.id);
    try {
      rmSync(join(dirname(statePath()), "tasks", `${record.id}.txt`), { force: true });
      rmSync(join(dirname(statePath()), "reports", `${record.id}.md`), { force: true });
    } catch {
      /* task/report file cleanup is best-effort */
    }
    return `✓ Closed agent ${record.name} (${notes.join(", ")})`;
  },
});

const registerrepo = tool({
  description:
    "Register a repo in the orchestrator registry (~/.config/opencode/orchestrator/repos.json) so spawnagent can create worktrees for it.",
  args: {
    name: z.string().describe("Short key for the repo, e.g. 'monodo'"),
    path: z.string().describe("Absolute or ~-relative path to the local clone, e.g. ~/repos/monodo"),
    setup: z
      .string()
      .optional()
      .describe("Optional setup script overriding the profile convention (~/.config/opencode/orchestrator/setups/<repo>.sh) — absolute path, or relative to repo root"),
    env: z
      .record(z.string(), z.string())
      .optional()
      .describe("Env vars injected into the agent's opencode process (e.g. MARKET_REGION)"),
  },
  async execute({ name, path, setup, env }) {
    const expanded = expandHome(path);
    if (!existsSync(expanded)) return `Error: path does not exist: ${expanded}`;
    if (!git.isGitRepo(expanded, exec)) return `Error: not a git repo: ${expanded}`;
    try {
      upsertRepo(registryPath(), { name, path, setup, env });
      return `✓ Registered repo '${name}' → ${path}${setup ? ` (setup: ${setup})` : ""}`;
    } catch (err) {
      return fail(err);
    }
  },
});

// ── agent-side tool ───────────────────────────────────────────────────

const REPORT_STATUS = { done: "done", blocked: "blocked", question: "question" };

const reportstatus = tool({
  description:
    "Report your status back to the orchestrator session and the user. Call this when you finish (done), hit a blocker (blocked), need a decision (question), or want to leave a progress note (note). Put any deliverable longer than one line (write-up, review, analysis) in `report` — never in the worktree or your terminal, neither of which the orchestrator can read reliably.",
  args: {
    kind: z.enum(["done", "blocked", "question", "note"]),
    message: z.string().describe("One-line summary, e.g. 'constraints added, ready for review'"),
    report: z
      .string()
      .optional()
      .describe("Full report/deliverable (markdown). Saved to a file whose path is delivered with the wake-up, so the orchestrator reads it directly."),
  },
  async execute({ kind, message, report }) {
    const agentId = process.env.OC_ORCH_AGENT_ID;
    const file = statePath();
    const state = loadState(file);
    const record = state.agents[agentId];
    if (!record) {
      return `Error: no agent record found for ${agentId} — was this session spawned by spawnagent?`;
    }
    let reportPath = null;
    if (report) {
      const dir = join(dirname(file), "reports");
      mkdirSync(dir, { recursive: true });
      reportPath = join(dir, `${agentId}.md`);
      writeFileSync(reportPath, report);
    }
    const patch = {
      lastReport: { kind, message, at: nowIso(), ...(reportPath ? { reportPath } : {}) },
      ...(REPORT_STATUS[kind] ? { status: REPORT_STATUS[kind] } : {}),
    };
    updateAgent(file, agentId, patch);
    try {
      cmux.notify({ title: `agent ${record.name}: ${kind}`, subtitle: message.slice(0, 80) }, exec);
      cmux.markUnread(record.tabRef, exec);
    } catch {
      /* notification is best-effort */
    }
    const saved = reportPath ? ` (full report saved to ${reportPath})` : "";
    return `✓ Reported '${kind}' to orchestrator: ${message}${saved}`;
  },
});

// ── plugin entry ──────────────────────────────────────────────────────

function agentNudge(agentId) {
  let who = `id ${agentId}`;
  try {
    const record = loadState(statePath()).agents[agentId];
    if (record) who = `'${record.name}' (${agentId}), repo ${record.repo}, branch ${record.branch}`;
  } catch {
    /* state unavailable — fall back to id only */
  }
  return [
    `ORCHESTRATED AGENT SESSION: you are agent ${who}, spawned by the opencode-orchestrator plugin.`,
    `Work autonomously in this worktree. When you finish the task, get blocked, or need a decision,`,
    `call the reportstatus tool (kind: done|blocked|question|note) with a one-line summary — the`,
    `orchestrator session and the user rely on these reports to know your state.`,
    `Any deliverable longer than one line (write-up, review, analysis) goes in reportstatus's`,
    `'report' arg — do NOT leave it in your terminal or write it into the worktree.`,
  ].join("\n");
}

const ORCHESTRATOR_NUDGE = [
  "ORCHESTRATOR TOOLS ACTIVE: you can spawn and supervise parallel agents on isolated worktrees",
  "(spawnagent, listagents, peekagent, sendtoagent, focusagent, closeagent, registerrepo).",
  "NEVER sleep, poll, or wait on an agent — not after spawnagent, not after sendtoagent. End your",
  "turn; a monitor wakes this session on every reportstatus (the user also gets a cmux notification).",
  "If a report includes a 'Full report:' path, Read that file — do not peekagent to scrape it.",
  "If something genuinely needs watching, spawn a monitor agent for it — never watch from here.",
  "Only call listagents/peekagent when the user asks.",
].join("\n");

async function OrchestratorServer(input) {
  const agentId = process.env.OC_ORCH_AGENT_ID;
  const isAgent = Boolean(agentId);
  serverUrl = input?.serverUrl ? String(input.serverUrl) : null;

  const hooks = {
    tool: isAgent
      ? {
          spawnagent,
          listagents,
          peekagent,
          sendtoagent,
          focusagent,
          closeagent,
          registerrepo,
          reportstatus,
        }
      : {
          spawnagent,
          listagents,
          peekagent,
          sendtoagent,
          focusagent,
          closeagent,
          registerrepo,
        },
  };

  hooks["experimental.chat.system.transform"] = async (_input, output) => {
    output.system.push(isAgent ? agentNudge(agentId) : ORCHESTRATOR_NUDGE);
  };

  if (!isAgent) {
    // Agent→session report delivery: reportstatus writes land in the shared
    // state file; on the user's next message we append fresh reports to it.
    // Track seen reports by key (not a timestamp watermark) so same-millisecond
    // writes can't slip through, and restarts don't re-dump history.
    const seen = new Set();
    try {
      for (const a of Object.values(loadState(statePath()).agents)) {
        if (a.lastReport?.at) seen.add(`${a.id}:${a.lastReport.at}`);
      }
    } catch {
      /* unreadable state — inject everything when it becomes readable */
    }

    hooks["chat.message"] = async (_input, output) => {
      try {
        const agents = Object.values(loadState(statePath()).agents);
        const fresh = agents.filter(
          (a) => a.lastReport?.at && !seen.has(`${a.id}:${a.lastReport.at}`),
        );
        if (fresh.length === 0) return;
        for (const a of fresh) seen.add(`${a.id}:${a.lastReport.at}`);

        const lines = fresh.map((a) => {
          const path = a.lastReport.reportPath ? ` — full report: ${a.lastReport.reportPath}` : "";
          return `- ${a.name} (${a.lastReport.kind}): ${a.lastReport.message}${path}`;
        });
        const block = [
          "",
          "[orchestrator] agent reports since your last check:",
          ...lines,
          "(listagents for details, peekagent to look, sendtoagent to reply)",
        ].join("\n");
        const textPart = [...(output.parts ?? [])]
          .reverse()
          .find((p) => p?.type === "text");
        if (textPart) textPart.text += block;
      } catch {
        /* report injection must never break the message flow */
      }
    };

    // In-process watcher: lives inside THIS session's plugin instance, so it
    // dies with the session instead of outliving it (no stale serverUrl, no
    // orphan process to manage). Requires a real client+serverUrl — absent
    // in tests, where chat.message injection is exercised directly instead.
    if (input?.client && serverUrl) {
      const stopWatcher = startWatcher({
        stateFile: statePath(),
        serverUrl,
        client: input.client,
      });
      hooks.dispose = async () => {
        stopWatcher();
      };
    }
  }

  if (isAgent) {
    hooks.event = async ({ event }) => {
      try {
        const file = statePath();

        // Backfill the linked opencode session id from any event that carries
        // one — session.created can fire before plugin init finishes, so it
        // must not be the only chance to learn it.
        const props = event.properties ?? {};
        const sessionID = props.info?.id ?? props.sessionID ?? props.info?.sessionID;
        if (sessionID) {
          const record = loadState(file).agents[agentId];
          if (record && !record.sessionID) updateAgent(file, agentId, { sessionID });
        }

        switch (event.type) {
          case "session.status": {
            const type = props.status?.type ?? props.type;
            if (type === "busy") {
              const record = loadState(file).agents[agentId];
              if (record && ["starting", "idle"].includes(record.status)) {
                updateAgent(file, agentId, { status: "working" });
              }
            }
            break;
          }
          case "session.idle": {
            const record = loadState(file).agents[agentId];
            if (record && ["starting", "working"].includes(record.status)) {
              updateAgent(file, agentId, { status: "idle" });
            }
            break;
          }
          case "session.error": {
            updateAgent(file, agentId, { status: "error" });
            break;
          }
        }
      } catch {
        /* status tracking must never break the session */
      }
    };
  }

  return hooks;
}

export default {
  id: "opencode-orchestrator",
  server: OrchestratorServer,
};
